using Microsoft.Data.Sqlite; using Pharmacie.Domain;
namespace Pharmacie.Infrastructure;
public sealed class SqliteProductRepository(SqliteConnectionFactory factory) : IProductRepository
{
 public async Task<IReadOnlyList<Product>> GetAllAsync(CancellationToken cancellationToken = default) { await using var c=factory.Create(); await using var cmd=c.CreateCommand(); cmd.CommandText="SELECT Id,Reference,Designation,CategoryId,Dosage,Forme,Unit,Barcode,SalePriceMinor,MinimumStock,IsActive FROM Products ORDER BY Designation"; var list=new List<Product>(); await using var r=await cmd.ExecuteReaderAsync(cancellationToken); while(await r.ReadAsync(cancellationToken)) list.Add(Read(r)); return list; }
 public async Task<Product?> GetByIdAsync(Guid id, CancellationToken cancellationToken = default) { await using var c=factory.Create(); await using var cmd=c.CreateCommand(); cmd.CommandText="SELECT Id,Reference,Designation,CategoryId,Dosage,Forme,Unit,Barcode,SalePriceMinor,MinimumStock,IsActive FROM Products WHERE Id=$id"; cmd.Parameters.AddWithValue("$id",id.ToString()); await using var r=await cmd.ExecuteReaderAsync(cancellationToken); return await r.ReadAsync(cancellationToken)?Read(r):null; }
 public async Task AddAsync(Product p, CancellationToken cancellationToken = default) { await using var c=factory.Create(); await using var cmd=c.CreateCommand(); cmd.CommandText="INSERT INTO Products(Id,Reference,Designation,CategoryId,Dosage,Forme,Unit,Barcode,SalePriceMinor,MinimumStock,IsActive,CreatedAt,UpdatedAt) VALUES($id,$ref,$designation,$category,$dosage,$forme,$unit,$barcode,$price,$minimum,1,$now,$now)"; cmd.Parameters.AddWithValue("$id",p.Id.ToString()); cmd.Parameters.AddWithValue("$ref",p.Reference); cmd.Parameters.AddWithValue("$designation",p.Designation); cmd.Parameters.AddWithValue("$category",p.CategoryId.ToString()); cmd.Parameters.AddWithValue("$dosage",(object?)p.Dosage??DBNull.Value); cmd.Parameters.AddWithValue("$forme",(object?)p.Forme??DBNull.Value); cmd.Parameters.AddWithValue("$unit",p.UniteVente); cmd.Parameters.AddWithValue("$barcode",(object?)p.CodeBarres??DBNull.Value); cmd.Parameters.AddWithValue("$price",Money.ToMinorUnits(p.PrixVente)); cmd.Parameters.AddWithValue("$minimum",p.SeuilMinimum); cmd.Parameters.AddWithValue("$now",DateTimeOffset.UtcNow.ToString("O")); await cmd.ExecuteNonQueryAsync(cancellationToken); }
 static Product Read(SqliteDataReader r)=>new(Guid.Parse(r.GetString(0)),r.GetString(1),r.GetString(2),Guid.Parse(r.GetString(3)),r.IsDBNull(4)?null:r.GetString(4),r.IsDBNull(5)?null:r.GetString(5),r.GetString(6),r.IsDBNull(7)?null:r.GetString(7),Money.FromMinorUnits(r.GetInt64(8)),r.GetDecimal(9),r.GetInt64(10)==1);
}
